import{_ as n,l as o,o as e,c as l,v as t,p as s,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"表分区","description":"","frontmatter":{"title":"表分区","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/table-partitioning.md","filePath":"cs/table-partitioning.md","lastUpdated":1789023840000}'),c={name:"cs/table-partitioning.md"};function h(A,a,_,m,B,u){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="表分区" tabindex="-1">表分区 <a class="header-anchor" href="#表分区" aria-label="Permalink to &quot;表分区&quot;">​</a></h1><div class="epigraph"><p>分区是声明的水平切：扫描只打开命中分区，维护与并行以分区为粒度；切错键则变成全部分区都扫。</p><footer>—— 据 Ramakrishnan and Gehrke；Leverenz et al. Oracle 分区；PostgreSQL 声明式分区</footer></div><p><a href="/cs/blob-storage">上一课</a>把大值撤出行扫描。本课不流式读段。缺口是表太大：统计、VACUUM、索引、查询仍当一个堆。表分区（partitioning）按键范围、列表或哈希把行分到子表，优化器做分区裁剪（partition pruning），执行器并行按分区。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 <a href="/cs/sharding">分片直觉</a> 偏分布式。本课单库内分区：同一模式、同一事务，只是物理多堆。缺口是<strong>裁剪合法性</strong>：谓词必须约束分区键且 sargable，否则扫描所有子表，比未分区还多个计划节点税。</p><p>维护：删旧范围分区等于丢掉冷数据，比 <code>DELETE</code>+vacuum 快。索引：局部索引每分区一份，全局索引跨分区（实现更重）。唯一约束若不含分区键，全局唯一贵。</p><p><span class="marginnote">声明式分区把路由写进计划。触发器路由是旧路径。本课声明。与分布式 shard 的差别是提交与故障域仍是一库。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选键：时间、租户、哈希 id。查询必须带键。连接：两表同键同切可分区智能连接（对应分区两两连），否则先 exchange。默认分区接住未列值，防止静默丢失。</p><p>迁移：从一堆拆成分区是模式演化课的重 I/O 脚本。附加：detach 分区变成普通表，服务归档。</p>',10)),(e(),s(E,null,{default:r(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E8%B0%93%E8%AF%8D%E5%90%AB%E5%88%86%E5%8C%BA%E9%94%AE%22%5D%20--%3E%20PRUNE%5B%22%E6%89%93%E5%BC%80%E5%AD%90%E9%9B%86%E5%88%86%E5%8C%BA%22%5D%0A%20%20PRED2%5B%22%E8%B0%93%E8%AF%8D%E4%B8%8D%E5%90%AB%E9%94%AE%22%5D%20--%3E%20ALL%5B%22%E6%89%AB%E5%85%A8%E9%83%A8%E5%88%86%E5%8C%BA%22%5D%0A%20%20PART%5B%22%E5%88%86%E5%8C%BA%22%5D%20--%3E%20PAR%5B%22%E5%B7%A5%E4%BA%BA%E5%90%84%E7%AE%A1%E4%B8%80%E5%88%86%E5%8C%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>zone map 在分区级就是约束本身。统计：每分区直方图，全局 NDV 要合并草图。计划回归：数据跨过分区边界，昨日裁一区、今日裁两区，属预期；无谓词突然不裁才是回归。</p><p>复制：物理复制所有分区文件；逻辑复制可按分区过滤。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 TDE。也不把分区当 5NF。分片再平衡是分布式课，单库分区 rebalance 是数据搬家脚本。</p><p>后课默认：大表按查询谓词选分区键；无键谓词等于未分区。透明加密与压缩：页在落盘前的变换，与切表正交。</p><p>分区裁剪是下推的亲戚，防火墙同样是函数包住分区键。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分区水平切堆，裁剪依赖分区键谓词。</li><li>局部索引与约束设计随键走；并行按分区。</li><li>透明加密与压缩下一课：落盘变换。</li><li>出处：Ramakrishnan and Gehrke；声明式分区实践。</li></ul>',9))])}const D=n(c,[["render",h]]);export{f as __pageData,D as default};
